@layer components {
  :where([data-send-aurora]) {
    --aurora-1: oklch(0.66 0.24 356);
    --aurora-2: oklch(0.71 0.19 41);
    --aurora-3: oklch(0.85 0.15 91);
    --aurora-4: oklch(0.86 0.03 235);
    --aurora-5: oklch(0.45 0.19 262);
    opacity: 0;
    animation: send-aurora-sweep calc(var(--duration-slow) * 4) var(--ease-emphasized) forwards;
  }

  :where([data-send-aurora] [data-column="center"]) {
    translate: 0 calc(var(--spacing) * -20);
  }

  :where([data-send-aurora] [data-band]) {
    filter: blur(var(--blur-xl));
  }

  :where([data-send-aurora] [data-band="1"]) {
    background-color: var(--aurora-1);
  }

  :where([data-send-aurora] [data-band="2"]) {
    background-color: var(--aurora-2);
  }

  :where([data-send-aurora] [data-band="3"]) {
    background-color: var(--aurora-3);
  }

  :where([data-send-aurora] [data-band="4"]) {
    background-color: var(--aurora-4);
  }

  :where([data-send-aurora] [data-band="5"]) {
    background-color: var(--aurora-5);
  }
}

@keyframes send-aurora-sweep {
  0% {
    opacity: 0;
    translate: 0 30%;
  }
  18% {
    opacity: 1;
  }
  60% {
    opacity: 0.85;
    translate: 0 4%;
  }
  100% {
    opacity: 0;
    translate: 0 -14%;
  }
}

"use client";

import type { CSSProperties } from "react";

export type SendAuroraProps = {
  sendCount: number;
  colors?: readonly [string, string, string, string, string];
};

const AURORA_BANDS = [1, 2, 3, 4, 5] as const;
const AURORA_COLUMNS = ["left", "center", "right"] as const;

type AuroraPaletteStyle = CSSProperties & Record<"--aurora-1" | "--aurora-2" | "--aurora-3" | "--aurora-4" | "--aurora-5", string>;

export function SendAurora({ sendCount, colors }: SendAuroraProps) {
  if (sendCount === 0) return null;

  const paletteOverride: AuroraPaletteStyle | undefined = colors
    ? {
        "--aurora-1": colors[0],
        "--aurora-2": colors[1],
        "--aurora-3": colors[2],
        "--aurora-4": colors[3],
        "--aurora-5": colors[4],
      }
    : undefined;

  return (
    <div key={sendCount} data-send-aurora="" className="flex size-full items-stretch" style={paletteOverride}>
      {AURORA_COLUMNS.map((column) => (
        <div key={column} data-column={column} className="flex h-full w-full flex-col items-stretch -space-y-3">
          {AURORA_BANDS.map((band) => (
            <div key={band} data-band={band} className="w-full flex-1" />
          ))}
        </div>
      ))}
    </div>
  );
}
